"use client";
// Coded reference prototype (React + Kursion UI). Built in code – NOT generated by Figma Make.
import { useEffect, useMemo, useRef, useState } from "react";
import { Plus, X } from "lucide-react";
import { Alert, Button, Card, DataTable, Dialog, FilterChips, Input, KursionRoot, SearchField, Select, StatusBadge, sortRows, type Column, type Sort } from "@/components/kursion";
import { statuses, type StatusId } from "@/lib/consistency/tokens";
import { formatDate, trainings, type Training } from "@/lib/consistency/data";
import "@/components/consistency-showcase/after.css";

const ORDER: StatusId[] = ["draft", "published", "open", "completed", "cancelled"];
const CATEGORIES: Training["category"][] = ["Management", "Digital skills", "Communication", "Compliance", "Finance"];
const FORMATS: Training["format"][] = ["Online", "Classroom", "Hybrid"];
const LECTURERS = [...new Set(trainings.map((t) => t.lecturer))].sort();

type Draft = { title: string; category: string; format: string; start: string; lecturer: string; seats: string };
const EMPTY: Draft = { title: "", category: "", format: "", start: "", lecturer: "", seats: "" };

function validate(d: Draft) {
  const e: Partial<Record<keyof Draft, string>> = {};
  if (d.title.trim().length < 5) e.title = "Enter a title of at least 5 characters.";
  if (!d.category) e.category = "Choose a category.";
  if (!d.format) e.format = "Choose a format.";
  if (!d.start) e.start = "Choose a start date.";
  else if (d.start < "2026-11-02") e.start = "The start date must be in the future.";
  if (!d.lecturer) e.lecturer = "Choose a lecturer.";
  const seats = Number(d.seats);
  if (!d.seats) e.seats = "Enter the number of seats.";
  else if (!Number.isInteger(seats) || seats < 4 || seats > 60) e.seats = "Use a whole number between 4 and 60.";
  return e;
}

function CreateTraining({ open, onClose, onCreate }: { open: boolean; onClose: () => void; onCreate: (t: Training) => void }) {
  const [d, setD] = useState<Draft>(EMPTY);
  const [tried, setTried] = useState(false);
  const errors = tried ? validate(d) : {};
  const set = (k: keyof Draft) => (v: string) => setD((o) => ({ ...o, [k]: v }));

  function submit(e: React.FormEvent) {
    e.preventDefault();
    setTried(true);
    const errs = validate(d);
    if (Object.keys(errs).length) {
      // Focus the first invalid field so keyboard and screen-reader users land on the problem.
      const name = (Object.keys(EMPTY) as (keyof Draft)[]).find((k) => errs[k]);
      (document.querySelector(`.k-modal [name="${name}"]`) as HTMLElement | null)?.focus();
      return;
    }
    onCreate({ id: `T-${1054 + Math.floor(Math.random() * 900)}`, title: d.title.trim(), category: d.category as Training["category"], format: d.format as Training["format"], start: d.start, lecturer: d.lecturer, seats: Number(d.seats), registered: 0, status: "draft", price: 0 });
    setD(EMPTY);
    setTried(false);
    onClose();
  }

  return (
    <Dialog open={open} onClose={() => { setTried(false); onClose(); }} title="New training" description="It is saved as a draft. You can publish it later." width="34rem">
      <form noValidate onSubmit={submit} className="mt-4 grid gap-4">
        <Input name="title" label="Title" required value={d.title} onChange={set("title")} error={errors.title} />
        <div className="cc-2col">
          <Select name="category" label="Category" required placeholder="Choose a category" value={d.category} onChange={set("category")} error={errors.category} options={CATEGORIES.map((c) => ({ value: c, label: c }))} />
          <Select name="format" label="Format" required placeholder="Choose a format" value={d.format} onChange={set("format")} error={errors.format} options={FORMATS.map((c) => ({ value: c, label: c }))} />
        </div>
        <div className="cc-2col">
          <Input name="start" type="date" label="Start date" required value={d.start} onChange={set("start")} error={errors.start} />
          <Input name="seats" type="number" label="Seats" required hint="Between 4 and 60." value={d.seats} onChange={set("seats")} error={errors.seats} />
        </div>
        <Select name="lecturer" label="Lecturer" required placeholder="Choose a lecturer" value={d.lecturer} onChange={set("lecturer")} error={errors.lecturer} options={LECTURERS.map((c) => ({ value: c, label: c }))} />
        <div className="k-modal__actions" style={{ marginTop: 4 }}>
          <Button variant="secondary" onClick={() => { setTried(false); onClose(); }}>Cancel</Button>
          <Button type="submit" icon={Plus}>Create training</Button>
        </div>
      </form>
    </Dialog>
  );
}

function Details({ t, onClose, focus }: { t: Training; onClose: () => void; focus: boolean }) {
  const ref = useRef<HTMLHeadingElement>(null);
  useEffect(() => { if (focus) ref.current?.focus(); }, [t.id, focus]);
  const free = t.seats - t.registered;
  return (
    <Card as="div">
      <div className="k-card__head">
        <div>
          <p className="k-small k-muted" style={{ margin: 0 }}>{t.id} · {t.category}</p>
          <h3 ref={ref} tabIndex={-1} className="k-h2" style={{ outline: "none" }}>{t.title}</h3>
        </div>
        <button type="button" className="k-btn" data-variant="secondary" data-size="sm" onClick={onClose} aria-label="Close details"><X className="k-icon" aria-hidden /></button>
      </div>
      <StatusBadge status={t.status} />
      <dl className="grid grid-cols-2 gap-3 text-sm">
        {[["Starts", formatDate(t.start)], ["Format", t.format], ["Lecturer", t.lecturer], ["Seats", `${t.registered} of ${t.seats} taken`], ["Free seats", String(free)], ["Status", statuses[t.status].meaning]].map(([k, v]) => (
          <div key={k}><dt className="k-muted" style={{ fontSize: "var(--k-font-size-caption)" }}>{k}</dt><dd style={{ margin: 0, fontWeight: 600 }}>{v}</dd></div>
        ))}
      </dl>
      <div className="h-2 overflow-hidden rounded-full bg-[var(--k-color-bg-canvas)]" role="img" aria-label={`${t.registered} of ${t.seats} seats taken`}>
        <div className="h-full rounded-full bg-[var(--k-color-action-primary)]" style={{ width: `${Math.min(100, (t.registered / t.seats) * 100)}%` }} />
      </div>
    </Card>
  );
}

export default function ReferencePrototype() {
  const [rows, setRows] = useState<Training[]>(trainings);
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<StatusId | "all">("all");
  const [sort, setSort] = useState<Sort>({ key: "start", dir: "asc" });
  const [selected, setSelected] = useState<string | null>(null);
  const [focusDetails, setFocusDetails] = useState(false);
  const [creating, setCreating] = useState(false);
  const [notice, setNotice] = useState("");
  // The notice is a live region (role="status"); focus returns to "New training" when the dialog closes.

  const columns: Column<Training>[] = useMemo(
    () => [
      { key: "title", header: "Training", sortValue: (t) => t.title, cell: (t) => <><span className="block font-semibold">{t.title}</span><span className="k-muted" style={{ fontSize: "var(--k-font-size-caption)" }}>{t.id} · {t.format}</span></> },
      { key: "start", header: "Starts", sortValue: (t) => t.start, cell: (t) => <span className="whitespace-nowrap">{formatDate(t.start)}</span> },
      { key: "seats", header: "Seats", numeric: true, sortValue: (t) => t.registered / t.seats, cell: (t) => `${t.registered} / ${t.seats}` },
      { key: "status", header: "Status", sortValue: (t) => ORDER.indexOf(t.status), cell: (t) => <StatusBadge status={t.status} /> },
      { key: "open", header: "Details", cell: (t) => <Button variant="secondary" size="sm" aria-label={`View details of ${t.title}`} onClick={() => { setSelected(t.id); setFocusDetails(true); }}>View</Button> },
    ],
    [],
  );
  const filtered = rows.filter((t) => (status === "all" || t.status === status) && `${t.title} ${t.lecturer} ${t.id}`.toLowerCase().includes(query.trim().toLowerCase()));
  const shown = sortRows(filtered, columns, sort);
  const sel = rows.find((t) => t.id === selected);

  return (
    <KursionRoot className="rounded-[20px] ring-1 ring-ink/10">
      <div className="cc-main">
        <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
          <div>
            <h3 className="k-h1">Trainings</h3>
            <p className="k-small k-muted" style={{ margin: "4px 0 0" }}>{rows.length} trainings · fictional data</p>
          </div>
          <Button icon={Plus} onClick={() => setCreating(true)}>New training</Button>
        </div>
        {notice && <div className="mb-3"><Alert tone="success">{notice}</Alert></div>}
        <div className="cc-toolbar">
          <SearchField value={query} onChange={setQuery} label="Search trainings" placeholder="Title, lecturer or ID" />
          <FilterChips legend="Status" value={status} onChange={setStatus} options={[{ value: "all", label: "All", count: rows.length }, ...ORDER.map((s) => ({ value: s, label: statuses[s].label, count: rows.filter((t) => t.status === s).length }))]} />
        </div>
        <p className="k-small k-muted" role="status" style={{ margin: "0 0 8px" }}>Showing {shown.length} of {rows.length} trainings</p>
        <div className={sel ? "grid gap-4 xl:grid-cols-[minmax(0,1fr)_20rem]" : ""}>
          <DataTable caption="Trainings" columns={columns} rows={shown} rowKey={(t) => t.id} sort={sort} onSort={setSort} empty={<><p style={{ margin: "0 0 8px" }}>No trainings match.</p><Button variant="secondary" size="sm" onClick={() => { setQuery(""); setStatus("all"); }}>Clear filters</Button></>} />
          {sel && <Details t={sel} focus={focusDetails} onClose={() => setSelected(null)} />}
        </div>
      </div>
      <CreateTraining
        open={creating}
        onClose={() => setCreating(false)}
        onCreate={(t) => {
          setRows((r) => [t, ...r]);
          setStatus("all");
          setQuery("");
          setSelected(t.id);
          setFocusDetails(false);
          setNotice(`“${t.title}” was created as a draft. (Demo – nothing was saved.)`);
        }}
      />
    </KursionRoot>
  );
}
